import 'dart:async';

import 'package:flutter/foundation.dart';
import 'package:voisss_butler_client/voisss_butler_client.dart';

import '../services/silence/silence_service.dart';

/// Entry ids in the gallery that were generated by a machine (planted via
/// the vocalize/TTS pipeline). Drives the "one of these voices is a
/// machine" reveal once a judge votes on it.
const kAgentEntryIds = <int>{2};

class SilenceProvider extends ChangeNotifier {
  final SilenceService _service = SilenceService();

  SilenceClip? clip;
  List<SilenceEntryView> entries = [];
  List<SilenceLeaderboardRow> leaderboard = [];

  bool loading = false;
  bool submitting = false;
  String? error;

  /// Entries this device has voted on (entryId → score). Drives the
  /// blind→reveal UX: personas show until you vote.
  final Map<int, int> myVotes = {};

  StreamSubscription<List<SilenceLeaderboardRow>>? _leaderboardSub;

  Future<void> load() async {
    loading = true;
    error = null;
    notifyListeners();
    try {
      clip = await _service.getActiveClip();
      if (clip != null) {
        entries = await _service.listEntries(clip!.id!);
        leaderboard = await _service.leaderboard(clip!.id!);
        _leaderboardSub?.cancel();
        _leaderboardSub =
            _service.watchLeaderboard(clip!.id!).listen((rows) {
          leaderboard = rows;
          notifyListeners();
        }, onError: (_) {});
      }
    } catch (e) {
      error = 'Could not reach the contest server. Check your connection.';
    } finally {
      loading = false;
      notifyListeners();
    }
  }

  Future<void> submitEntry({
    required String displayName,
    required Uint8List audioBytes,
    required String audioFormat,
  }) async {
    if (clip == null) return;
    submitting = true;
    error = null;
    notifyListeners();
    try {
      final entry = await _service.submit(
        clipId: clip!.id!,
        displayName: displayName,
        audioBytes: audioBytes,
        audioFormat: audioFormat,
      );
      entries = [entry, ...entries];
    } catch (e) {
      error = 'Upload failed — please try again.';
    } finally {
      submitting = false;
      notifyListeners();
    }
  }

  Future<void> vote(int entryId, int score) async {
    try {
      leaderboard = await _service.castVote(entryId, score);
      myVotes[entryId] = score;
      if (clip != null) {
        entries = await _service.listEntries(clip!.id!);
      }
      notifyListeners();
    } catch (e) {
      error = 'Vote could not be recorded.';
      notifyListeners();
    }
  }

  @override
  void dispose() {
    _leaderboardSub?.cancel();
    _service.dispose();
    super.dispose();
  }
}
